head.script:
var currentLoginType = "normal";
var isKakaoAuthenticated = false;

scwin.onpageload = function () {
    var mode = $p.getParameter("mode");
    var email = $p.getParameter("email");
    var nickname = $p.getParameter("nickname");

    // 체크박스 초기화
    var chk = document.getElementById("chk_agree_html");
    if (chk) {
        chk.checked = (signup_dma.get("agreeTerms") === "Y");
    }

    top.window.onresize = scwin.throttle(function () {
        scwin.centerPopup("signUpCompletePopup", 0);
    }, 200);

    console.log("onpageload - mode:", mode);

    if (mode === "kakao" && email && nickname) {
        currentLoginType = "kakao";
        isKakaoAuthenticated = true;

        var decodedEmail = decodeURIComponent(email);
        var decodedNickname = decodeURIComponent(nickname);

        // 데이터맵 설정
        signup_dma.set("userName", decodedNickname);
        signup_dma.set("email", decodedEmail);

        // 직접 input 값도 설정 (강제)
        setTimeout(function () {
            name_input.setValue(decodedNickname);
            email_input.setValue(decodedEmail);
            loginTypeSelect.setValue("kakao");
            scwin.refreshUI();
        }, 100);
    } else {
        currentLoginType = "normal";
        isKakaoAuthenticated = false;
    }

    // 커스텀 팝업 레이어 생성
    scwin.createPopupLayer();
    scwin.refreshUI();

    // 개선된 스타일 적용 로직
    setTimeout(scwin.forceApplyStyles, 300);
    setTimeout(scwin.enhancedStyleForcing, 500);
    setTimeout(scwin.enhancedStyleForcing, 1000);
    setTimeout(scwin.forceKakaoButtonStyle, 100);
    setTimeout(scwin.forceKakaoButtonStyle, 500);
    setTimeout(scwin.forceKakaoButtonStyle, 1000);

    // 스타일 감시자 설정
    scwin.setupStyleObserver();

    // 주기적 스타일 재적용 (더 강력하게)
    setInterval(scwin.enhancedStyleForcing, 3000);
    setInterval(scwin.forceKakaoButtonStyle, 2000);
};

// 강화된 카카오 버튼 스타일 적용 함수
scwin.forceKakaoButtonStyle = function() {
    var kakaoBtn = document.getElementById('btn_kakao_auth');
    if (kakaoBtn) {
        // 모든 클래스 제거
        kakaoBtn.className = '';

        // 인라인 스타일로 강제 적용
        kakaoBtn.style.cssText = `
            width: 100% !important;
            height: 52px !important;
            background: #FEE500 !important;
            background-color: #FEE500 !important;
            background-image: none !important;
            color: #1a1a1a !important;
            border: 2px solid #F9CC00 !important;
            padding: 14px 24px !important;
            border-radius: 12px !important;
            font-size: 16px !important;
            font-weight: 800 !important;
            cursor: pointer !important;
            box-sizing: border-box !important;
            display: block !important;
        `;

        // 하위 요소들도 강제 적용
        var allElements = kakaoBtn.querySelectorAll('*');
        for (var i = 0; i < allElements.length; i++) {
            allElements[i].style.cssText = `
                color: #1a1a1a !important;
                background: transparent !important;
                font-weight: 800 !important;
            `;
        }
    }
};

// 기존 forceApplyStyles 함수 개선
scwin.forceApplyStyles = function() {
    console.log("Force apply styles started");

    // 카카오 버튼 스타일 강제 적용
    var kakaoBtn = document.getElementById('btn_kakao_auth');
    if (kakaoBtn) {
        kakaoBtn.style.setProperty('background', '#FEE500', 'important');
        kakaoBtn.style.setProperty('background-color', '#FEE500', 'important');
        kakaoBtn.style.setProperty('background-image', 'none', 'important');
        kakaoBtn.style.setProperty('color', '#1a1a1a', 'important');
        kakaoBtn.style.setProperty('border', '2px solid #F9CC00', 'important');
        kakaoBtn.style.setProperty('border-color', '#F9CC00', 'important');

        // 내부 텍스트 요소들도 강제 적용
        var kakaoLabels = kakaoBtn.querySelectorAll('*');
        for (var i = 0; i < kakaoLabels.length; i++) {
            kakaoLabels[i].style.setProperty('color', '#1a1a1a', 'important');
            kakaoLabels[i].style.setProperty('background', 'transparent', 'important');
        }
    }

    // 회원가입 버튼 스타일 강제 적용
    var signupBtn = document.getElementById('trigger1');
    if (signupBtn) {
        signupBtn.style.setProperty('width', '100%', 'important');
        signupBtn.style.setProperty('background', 'linear-gradient(135deg, rgb(54, 116, 181) 0%, rgb(87, 143, 202) 50%, rgb(74, 144, 226) 100%)', 'important');
        signupBtn.style.setProperty('background-color', 'rgb(54, 116, 181)', 'important');
        signupBtn.style.setProperty('color', '#ffffff', 'important');
        signupBtn.style.setProperty('border', 'none', 'important');

        // 내부 텍스트 요소들도 강제 적용
        var signupLabels = signupBtn.querySelectorAll('*');
        for (var j = 0; j < signupLabels.length; j++) {
            signupLabels[j].style.setProperty('color', '#ffffff', 'important');
            signupLabels[j].style.setProperty('background', 'transparent', 'important');
        }
    }

    // 중복검사 버튼 스타일 강제 적용
    var checkBtn = document.getElementById('btn_check');
    if (checkBtn) {
        checkBtn.style.setProperty('background', 'linear-gradient(135deg, rgb(54, 116, 181) 0%, rgb(87, 143, 202) 50%, rgb(74, 144, 226) 100%)', 'important');
        checkBtn.style.setProperty('color', '#ffffff', 'important');

        // 내부 텍스트 요소들도 강제 적용
        var checkLabels = checkBtn.querySelectorAll('*');
        for (var k = 0; k < checkLabels.length; k++) {
            checkLabels[k].style.setProperty('color', '#ffffff', 'important');
            checkLabels[k].style.setProperty('background', 'transparent', 'important');
        }
    }

    console.log("Force apply styles completed");
};

// 새로 추가된 강화된 스타일 강제 적용 함수
scwin.enhancedStyleForcing = function() {
    console.log("Enhanced style forcing started");

    // 카카오 버튼 스타일 강제 적용 - 모든 가능한 속성
    var kakaoBtn = document.getElementById('btn_kakao_auth');
    if (kakaoBtn) {
        // 모든 배경 관련 속성 강제 설정
        kakaoBtn.style.setProperty('background', '#FEE500', 'important');
        kakaoBtn.style.setProperty('background-color', '#FEE500', 'important');
        kakaoBtn.style.setProperty('background-image', 'none', 'important');
        kakaoBtn.style.setProperty('color', '#1a1a1a', 'important');
        kakaoBtn.style.setProperty('border', '2px solid #F9CC00', 'important');
        kakaoBtn.style.setProperty('border-color', '#F9CC00', 'important');
        kakaoBtn.style.setProperty('width', '100%', 'important');

        // 웹스퀘어 프레임워크 기본 클래스 제거 시도
        if (kakaoBtn.className) {
            kakaoBtn.className = kakaoBtn.className.replace(/w2-btn[^\s]*/g, '');
            kakaoBtn.className = kakaoBtn.className.replace(/w2-trigger[^\s]*/g, '');
        }

        // 모든 하위 요소에도 적용
        var allKakaoElements = kakaoBtn.querySelectorAll('*');
        for (var i = 0; i < allKakaoElements.length; i++) {
            allKakaoElements[i].style.setProperty('color', '#1a1a1a', 'important');
            allKakaoElements[i].style.setProperty('background', 'transparent', 'important');
            allKakaoElements[i].style.setProperty('background-color', 'transparent', 'important');
        }

        console.log("Enhanced kakao button style applied");
    }

    // 회원가입 버튼 스타일 강제 적용
    var signupBtn = document.getElementById('trigger1');
    if (signupBtn) {
        signupBtn.style.setProperty('width', '100%', 'important');
        signupBtn.style.setProperty('background', 'linear-gradient(135deg, rgb(54, 116, 181) 0%, rgb(87, 143, 202) 50%, rgb(74, 144, 226) 100%)', 'important');
        signupBtn.style.setProperty('background-color', 'rgb(54, 116, 181)', 'important');
        signupBtn.style.setProperty('color', '#ffffff', 'important');
        signupBtn.style.setProperty('border', 'none', 'important');
        signupBtn.style.setProperty('border-color', 'transparent', 'important');

        // 웹스퀘어 프레임워크 기본 클래스 제거 시도
        if (signupBtn.className) {
            signupBtn.className = signupBtn.className.replace(/w2-btn[^\s]*/g, '');
            signupBtn.className = signupBtn.className.replace(/w2-trigger[^\s]*/g, '');
        }

        // 모든 하위 요소에도 적용
        var allSignupElements = signupBtn.querySelectorAll('*');
        for (var j = 0; j < allSignupElements.length; j++) {
            allSignupElements[j].style.setProperty('color', '#ffffff', 'important');
            allSignupElements[j].style.setProperty('background', 'transparent', 'important');
            allSignupElements[j].style.setProperty('background-color', 'transparent', 'important');
        }

        console.log("Enhanced signup button style applied");
    }

    // 중복검사 버튼도 함께 처리
    var checkBtn = document.getElementById('btn_check');
    if (checkBtn) {
        checkBtn.style.setProperty('background', 'linear-gradient(135deg, rgb(54, 116, 181) 0%, rgb(87, 143, 202) 50%, rgb(74, 144, 226) 100%)', 'important');
        checkBtn.style.setProperty('color', '#ffffff', 'important');
        checkBtn.style.setProperty('border', 'none', 'important');

        if (checkBtn.className) {
            checkBtn.className = checkBtn.className.replace(/w2-btn[^\s]*/g, '');
            checkBtn.className = checkBtn.className.replace(/w2-trigger[^\s]*/g, '');
        }

        var allCheckElements = checkBtn.querySelectorAll('*');
        for (var k = 0; k < allCheckElements.length; k++) {
            allCheckElements[k].style.setProperty('color', '#ffffff', 'important');
            allCheckElements[k].style.setProperty('background', 'transparent', 'important');
            allCheckElements[k].style.setProperty('background-color', 'transparent', 'important');
        }

        console.log("Enhanced check button style applied");
    }

    console.log("Enhanced style forcing completed");
};

// DOM 변경 감지 및 자동 스타일 재적용
scwin.setupStyleObserver = function() {
    if (typeof MutationObserver !== 'undefined') {
        var observer = new MutationObserver(function(mutations) {
            var needsStyleUpdate = false;
            mutations.forEach(function(mutation) {
                if (mutation.type === 'attributes' && 
                    (mutation.target.id === 'btn_kakao_auth' || 
                     mutation.target.id === 'trigger1' || 
                     mutation.target.id === 'btn_check')) {
                    needsStyleUpdate = true;
                }
            });

            if (needsStyleUpdate) {
                setTimeout(scwin.enhancedStyleForcing, 50);
                setTimeout(scwin.forceKakaoButtonStyle, 50);
            }
        });

        // 버튼들 감시 시작
        setTimeout(function() {
            var kakaoBtn = document.getElementById('btn_kakao_auth');
            var signupBtn = document.getElementById('trigger1');
            var checkBtn = document.getElementById('btn_check');

            if (kakaoBtn) observer.observe(kakaoBtn, { attributes: true, attributeFilter: ['class', 'style'] });
            if (signupBtn) observer.observe(signupBtn, { attributes: true, attributeFilter: ['class', 'style'] });
            if (checkBtn) observer.observe(checkBtn, { attributes: true, attributeFilter: ['class', 'style'] });

            console.log("Style observer setup completed");
        }, 1000);
    }
};

// HTML 체크박스 상태 변경 핸들러 - 전역 함수로 등록
window.htmlCheckbox_onchange = function(checkbox) {
    if (typeof scwin !== 'undefined' && scwin.htmlCheckbox_onchange) {
        scwin.htmlCheckbox_onchange(checkbox);
    }
};

// scwin 객체의 체크박스 핸들러
scwin.htmlCheckbox_onchange = function(checkbox) {
    try {
        signup_dma.set("agreeTerms", checkbox.checked ? "Y" : "N");
        console.log("동의 상태 변경:", checkbox.checked ? "Y" : "N");
    } catch (e) {
        console.error("체크박스 상태 변경 오류:", e);
    }
};

// 팝업 레이어 생성 함수
scwin.createPopupLayer = function () {
    // 팝업이 이미 존재하면 다시 만들지 않음
    if (document.getElementById('customAlertPopup')) return;

    var popupHtml = 
        "<div id='customAlertPopup' style='position: fixed; top: 0; left: 0; width: 100%; height: 100%; background: rgba(0,0,0,0.5); z-index: 9999; display: none; align-items: center; justify-content: center; font-family: \"Pretendard\", sans-serif;'>" +
            "<div style='background: white; padding: 24px; border-radius: 16px; box-shadow: 0 20px 40px rgba(54, 116, 181, 0.15); min-width: 320px; max-width: 450px; text-align: center; box-sizing: border-box;'>" +
                "<div id='popupMessage' style='margin-bottom: 24px; font-size: 16px; line-height: 1.6; color: #2d3748; white-space: pre-wrap; word-break: break-word;'></div>" +
                "<div>" +
                    "<button id='popupConfirm' style='background: linear-gradient(135deg, rgb(54, 116, 181) 0%, rgb(87, 143, 202) 50%, rgb(74, 144, 226) 100%); color: white; border: none; padding: 12px 24px; margin: 0 5px; border-radius: 8px; cursor: pointer; font-size: 14px; font-weight: 500; transition: transform 0.2s ease;'>확인</button>" +
                    "<button id='popupCancel' style='background: linear-gradient(135deg, #8e9aaf 0%, #6c7b7f 100%); color: white; border: none; padding: 12px 24px; margin: 0 5px; border-radius: 8px; cursor: pointer; font-size: 14px; font-weight: 500; transition: transform 0.2s ease;'>취소</button>" +
                "</div>" +
            "</div>" +
        "</div>";

    document.body.insertAdjacentHTML('beforeend', popupHtml);
};

// 팝업 표시 함수
scwin.showPopup = function (message, isConfirm, callback) {
    var popup = document.getElementById('customAlertPopup');
    if (!popup) {
        // 혹시 팝업이 없는 경우를 대비해 생성
        scwin.createPopupLayer();
        popup = document.getElementById('customAlertPopup');
    }

    var messageEl = document.getElementById('popupMessage');
    var confirmBtn = document.getElementById('popupConfirm');
    var cancelBtn = document.getElementById('popupCancel');

    // 메시지에 줄바꿈(\n)이 있을 경우 HTML <br> 태그로 변환
    messageEl.innerHTML = message.replace(/\\n/g, '<br>');

    if (isConfirm) {
        cancelBtn.style.display = 'inline-block';
        confirmBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback(true);
        };
        cancelBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback(false);
        };
    } else {
        cancelBtn.style.display = 'none';
        confirmBtn.onclick = function () {
            popup.style.display = 'none';
            if (callback) callback();
        };
    }

    popup.style.display = 'flex';
};

scwin.loginTypeSelect_onchange = function () {
    currentLoginType = loginTypeSelect.getValue();
    isKakaoAuthenticated = false;

    if (currentLoginType === "kakao") {
        signup_dma.set("userName", "");
        signup_dma.set("email", "");
        signup_dma.set("password", "");
        signup_dma.set("passwordConfirm", "");
    }

    scwin.refreshUI();
    // UI 변경 후 강화된 스타일 재적용
    setTimeout(function() {
        scwin.forceApplyStyles();
        scwin.enhancedStyleForcing();
        scwin.forceKakaoButtonStyle();
    }, 100);
};

scwin.refreshUI = function () {
    console.log("refreshUI - currentLoginType:", currentLoginType);

    // 라디오 버튼 강제 설정
    loginTypeSelect.setValue(currentLoginType);

    var isNormal = (currentLoginType === "normal");

    // UI 표시/숨김
    grp_kakao_info.setStyle("display", isNormal ? "none" : "block");
    grp_kakao_auth.setStyle("display", (!isNormal && !isKakaoAuthenticated) ? "block" : "none");
    grp_kakao_user_info.setStyle("display", (!isNormal && isKakaoAuthenticated) ? "block" : "none");

    // 읽기전용 설정 - 다시 한번 강제 적용
    setTimeout(function () {
        name_input.setReadOnly(!isNormal);
        email_input.setReadOnly(!isNormal);
    }, 50);

    btn_check.setStyle("display", isNormal ? "inline-block" : "none");
    grp_pwd.setStyle("display", isNormal ? "block" : "none");
    grp_pwd_confirm.setStyle("display", isNormal ? "block" : "none");
    grp_agree.setStyle("display", isNormal ? "block" : "none");

    if (isNormal) {
        trigger1.setLabel("회원가입");
    } else {
        trigger1.setLabel("카카오 회원가입");
    }

    // UI 변경 후 강화된 스타일 재적용
    setTimeout(function() {
        scwin.enhancedStyleForcing();
        scwin.forceKakaoButtonStyle();
    }, 200);
};

scwin.btn_kakao_auth_onclick = function () {
    $c.sbm.execute(kakaoAuthProcess);
};

scwin.kakaoAuthProcess_submitdone = function (e) {
    if (e.responseStatusCode === 200 && e.responseJSON.success && e.responseJSON.loginUrl) {
        location.href = e.responseJSON.loginUrl;
    } else {
        scwin.showPopup("카카오 인증 URL을 가져오는데 실패했습니다.\n잠시 후 다시 시도해주세요.");
        console.log("카카오 인증 URL 호출 실패");
    }
};

scwin.trigger1_onclick = function () {
    if (currentLoginType === "normal") {
        // 1) 필수 입력값 검증
        if (!scwin.validateNormal()) return;
        // 3) 회원가입 요청 실행
        signup_dma.set("loginType", "normal");
        $c.sbm.execute(signupProcess);

    } else {
        // 카카오 회원가입 모드
        if (!scwin.validateKakao()) return;
        signup_dma.set("loginType", "kakao");
        $c.sbm.execute(signupProcess);
    }
};

scwin.btn_check_onclick = function () {
    if (currentLoginType === "normal") {
        console.log("이메일 중복검사 전 데이터:");
        console.log("email:", signup_dma.get("email"));
        $c.sbm.execute(emailCheck);
    } else {
        console.log("카카오 회원가입에서는 이메일 중복검사가 필요하지 않습니다.");
        scwin.showPopup("카카오 회원가입에서는 이메일 중복검사가 필요하지 않습니다.");
    }
};

scwin.validateNormal = function () {
    var u = signup_dma.get("userName"),
        m = signup_dma.get("email"),
        p = signup_dma.get("password"),
        pc = signup_dma.get("passwordConfirm"),
        d = signup_dma.get("subDomain");

    if (!u || u.trim() === "") { 
        scwin.showPopup("이름을 입력해주세요."); 
        console.log("이름을 입력해주세요"); 
        return false; 
    }
    if (!m || m.trim() === "") { 
        scwin.showPopup("이메일을 입력해주세요."); 
        console.log("이메일을 입력해주세요"); 
        return false; 
    }
    if (!p || p.trim() === "") { 
        scwin.showPopup("비밀번호를 입력해주세요."); 
        console.log("비밀번호를 입력해주세요"); 
        return false; 
    }
    if (p.length < 8) { 
        scwin.showPopup("비밀번호는 8자 이상이어야 합니다."); 
        console.log("비밀번호는 8자 이상이어야 합니다"); 
        return false; 
    }
    if (p !== pc) { 
        scwin.showPopup("비밀번호가 일치하지 않습니다."); 
        console.log("비밀번호가 일치하지 않습니다"); 
        return false; 
    }
    if (!d || d.trim() === "") { 
        scwin.showPopup("테넌트ID를 입력해주세요."); 
        console.log("테넌트ID를 입력해주세요"); 
        return false; 
    }
    if (signup_dma.get("agreeTerms") !== "Y") {
        scwin.showPopup("개인정보 수집 및 이용에 동의해주세요.");
        return false;
    }
    return true;
};

scwin.validateKakao = function () {
    var t = signup_dma.get("tenantName"),
        d = signup_dma.get("subDomain");
    if (!t || t.trim() === "") {
        scwin.showPopup("회사명을 입력해주세요.");
        console.log("회사명을 입력해주세요");
        return false;
    }
    if (!d || d.trim() === "") {
        scwin.showPopup("테넌트ID를 입력해주세요.");
        console.log("테넌트ID를 입력해주세요");
        return false;
    }
    return true;
};

scwin.signupProcess_submitdone = function (e) {
    if (e.responseStatusCode === 200) {
        console.log("회원가입 완료");
        var popupID = "signUpCompletePopup";
        var src = "/InsWebApp/main/sign_up_success.xml";
        var jsnPopupData = {
            "type": "json",
            "name": "admin_param",
            "data": {
                "email": email_input.getValue(),
                "name": name_input.getValue(),
                "company": company_input.getValue(),
                "tenant": tenant_input.getValue(),
            }
        };
        scwin.showPopup("회원가입이 성공적으로 완료되었습니다!\n환영합니다!", false, function () {
            scwin.createPopUp(popupID, "회원가입성공", jsnPopupData, src, 550, 900);
        });

    } else {
        var errorMsg = "회원가입 처리 중 오류가 발생했습니다.";
        if (e.responseJSON && e.responseJSON.message) {
            errorMsg = e.responseJSON.message;
        }
        scwin.showPopup(errorMsg);
    }
};

scwin.throttle = function (callback, delay) {
    var lastCall = 0;
    return function () {
        var now = new Date().getTime();
        if (now - lastCall >= delay) {
            lastCall = now;
            callback();
        }
    };
}

scwin.centerPopup = function (popupId, offsetY) {
    if (typeof offsetY === 'undefined') offsetY = 0;
    var pop = $p.getPopup(popupId);
    if (pop) {
        var width = pop.popupWin.getSize("width");
        var height = pop.popupWin.getSize("height");
        var left1 = (top.window.innerWidth - width) / 2;
        var top1 = (top.window.innerHeight - height) / 2 + offsetY;
        pop.popupWin.setPosition(left1, top1);
    }
};

scwin.createPopUp = function (_id, _name, _jsnData, url, _popupWidth, _popupHeight) {
    if ($p.getPopup(_id)) {
        console.log("Popup with ID '" + _id + "' already exists. Skipping creation.");
        return;
    }
    var popupWidth = _popupWidth;
    var popupHeight = _popupHeight;
    var topPosition = (window.innerHeight - popupHeight) / 2;
    var leftPosition = (window.innerWidth - popupWidth) / 2;
    var options = {
        id: _id,
        type: "pageFramePopup",
        width: popupWidth,
        height: popupHeight,
        autoSize: true,
        top: topPosition + "px",
        left: leftPosition + "px",
        popupName: _name,
        modal: true,
        closeAction: "scwin.popup_closeAction",
        dataObject: _jsnData,
    };
    $p.openPopup(url, options);
}

/* 이메일 중복검사 완료 */
scwin.emailCheck_submitdone = function (e) {
    console.log("이메일 중복검사 응답:", e);

    if (e.responseStatusCode === 200) {
        // 서버에서 온 문자열 메시지를 바로 alert로 표시
        scwin.showPopup(e.responseText);
    } else {
        scwin.showPopup("이메일 중복검사 중 오류가 발생했습니다.\n잠시 후 다시 시도해주세요.");
    }
};

scwin.popup_closeAction = function (argRuntimeID, argJsnInfo) {
    // argRuntimeID : 팝업의 실행 시점 아이디
    // argJsnInfo : 팝업의 부가 정보를 담은 JSON 객체
    // argJsnInfo.isCloseButtonClick : [true, false] 팝업의 닫기 버튼을 클릭해서 호출되었는지의 여부

    // 팝업객체 접근
    // var popObj = $p.getPopupWindow(argRuntimeID);

    console.log("메인페이지로 이동")
    location.href = "/InsWebApp/websquare/websquare.html?w2xPath=/InsWebApp/main/unicon_main.xml";

    return true; //팝업 닫기 (반환 값이 true인 경우만 팝업이 닫힘)
};
